using System.Diagnostics;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenTelemetry;
using OpenTelemetry.Trace;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode – validates that AI calls emit the expected OpenTelemetry spans.
/// </summary>
public class TelemetryTests
{
    private static readonly string ModelId = Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";
    private static readonly string Endpoint = Environment.GetEnvironmentVariable("EVAL_ENDPOINT") ?? "https://api.openai.com/v1";
    private static readonly string ApiKey = Environment.GetEnvironmentVariable("EVAL_API_KEY") ?? "";

    [Fact]
    public async Task ChatCompletion_EmitsExpectedSpans()
    {
        var exportedSpans = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("OpenAI.*")
            .AddInMemoryExporter(exportedSpans)
            .Build();

        var client = CreateChatClient();

        var response = await client.GetResponseAsync("Say hello in one word.");

        tracerProvider.ForceFlush();

        Assert.NotEmpty(exportedSpans);

        var chatSpan = exportedSpans.FirstOrDefault(s => s.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));
        Assert.NotNull(chatSpan);
        Assert.Equal(ActivityStatusCode.Unset, chatSpan.Status);
    }

    [Fact]
    public async Task ChatCompletion_SpanContainsModelMetadata()
    {
        var exportedSpans = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("OpenAI.*")
            .AddInMemoryExporter(exportedSpans)
            .Build();

        var client = CreateChatClient();

        var response = await client.GetResponseAsync("What is 2+2?");

        tracerProvider.ForceFlush();

        var chatSpan = exportedSpans.First(s => s.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));
        var tags = chatSpan.Tags.ToDictionary(t => t.Key, t => t.Value);

        Assert.True(
            tags.ContainsKey("gen_ai.request.model") || tags.ContainsKey("gen_ai.response.model"),
            "Span should contain model information");
    }

    [Fact]
    public async Task MultiTurn_EmitsSpanPerTurn()
    {
        var exportedSpans = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("OpenAI.*")
            .AddInMemoryExporter(exportedSpans)
            .Build();

        var client = CreateChatClient();
        var history = new List<ChatMessage> { new(ChatRole.User, "Hi") };

        var r1 = await client.GetResponseAsync(history);
        history.AddRange(r1.Messages);
        history.Add(new ChatMessage(ChatRole.User, "Thanks"));

        await client.GetResponseAsync(history);

        tracerProvider.ForceFlush();

        var chatSpans = exportedSpans
            .Where(s => s.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase))
            .ToList();

        Assert.True(chatSpans.Count >= 2, $"Expected at least 2 chat spans, got {chatSpans.Count}");
    }

    private static IChatClient CreateChatClient()
    {
        return new OpenAI.OpenAIClient(ApiKey)
            .GetChatClient(ModelId)
            .AsIChatClient()
            .AsBuilder()
            .UseOpenTelemetry()
            .Build();
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Quality mode – uses LLM-as-judge evaluators to score responses on
/// relevance, coherence, fluency, and groundedness.
/// </summary>
public class QualityTests
{
    private static readonly string ModelId = Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";
    private static readonly string JudgeModel = Environment.GetEnvironmentVariable("EVAL_JUDGE_MODEL") ?? "gpt-4o";
    private static readonly string Endpoint = Environment.GetEnvironmentVariable("EVAL_ENDPOINT") ?? "https://api.openai.com/v1";
    private static readonly string ApiKey = Environment.GetEnvironmentVariable("EVAL_API_KEY") ?? "";

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Response_MeetsQualityThresholds(string name, List<string> turns, string topic)
    {
        var chatClient = CreateChatClient(ModelId);
        var judgeClient = CreateChatClient(JudgeModel);

        // Build conversation
        var history = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a supportive life coach. Be concise and empathetic.")
        };

        ChatResponse? lastResponse = null;
        foreach (var turn in turns)
        {
            history.Add(new ChatMessage(ChatRole.User, turn));
            lastResponse = await chatClient.GetResponseAsync(history);
            history.AddRange(lastResponse.Messages);
        }

        Assert.NotNull(lastResponse);
        var responseText = lastResponse.Text;

        // Evaluate with LLM-as-judge
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(
                turns,
                lastResponse,
                judgeClient);

            foreach (var metric in result)
            {
                Assert.True(
                    metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                    $"[{name}] {metric.Key} scored below threshold: {metric.Value}");
            }
        }
    }

    public static IEnumerable<object[]> GetScenarios()
    {
        var json = File.ReadAllText(Path.Combine("Scenarios", "coaching.json"));
        var scenarios = JsonSerializer.Deserialize<List<ScenarioDefinition>>(json)!;

        foreach (var scenario in scenarios)
        {
            yield return new object[]
            {
                scenario.Name,
                scenario.Turns.Select(t => t.User).ToList(),
                scenario.Expectations.Topic
            };
        }
    }

    private static IChatClient CreateChatClient(string model)
    {
        return new OpenAI.OpenAIClient(ApiKey)
            .GetChatClient(model)
            .AsIChatClient();
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Xunit;
using Xunit.Abstractions;

namespace MyApp.Evals;

/// <summary>
/// Compare mode – runs the same scenarios against two model configurations
/// and reports side-by-side quality scores.
/// </summary>
public class CompareTests
{
    private readonly ITestOutputHelper _output;

    private static readonly string BaselineModel = Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini";
    private static readonly string CandidateModel = Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o";
    private static readonly string JudgeModel = Environment.GetEnvironmentVariable("EVAL_JUDGE_MODEL") ?? "gpt-4o";
    private static readonly string ApiKey = Environment.GetEnvironmentVariable("EVAL_API_KEY") ?? "";

    public CompareTests(ITestOutputHelper output)
    {
        _output = output;
    }

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Candidate_ScoredAgainstBaseline(string name, List<string> turns)
    {
        var judgeClient = CreateChatClient(JudgeModel);

        var baselineResponse = await RunScenario(BaselineModel, turns);
        var candidateResponse = await RunScenario(CandidateModel, turns);

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var baselineScores = new Dictionary<string, double>();
        var candidateScores = new Dictionary<string, double>();

        foreach (var evaluator in evaluators)
        {
            var baseResult = await evaluator.EvaluateAsync(turns, baselineResponse, judgeClient);
            var candResult = await evaluator.EvaluateAsync(turns, candidateResponse, judgeClient);

            foreach (var metric in baseResult)
            {
                if (metric.Value is NumericMetricValue num)
                    baselineScores[metric.Key] = num.Value ?? 0;
            }

            foreach (var metric in candResult)
            {
                if (metric.Value is NumericMetricValue num)
                    candidateScores[metric.Key] = num.Value ?? 0;
            }
        }

        // Report comparison
        _output.WriteLine($"Scenario: {name}");
        _output.WriteLine($"{"Metric",-20} {"Baseline (" + BaselineModel + ")",-30} {"Candidate (" + CandidateModel + ")",-30} Delta");
        _output.WriteLine(new string('-', 100));

        foreach (var key in baselineScores.Keys)
        {
            var bScore = baselineScores.GetValueOrDefault(key);
            var cScore = candidateScores.GetValueOrDefault(key);
            var delta = cScore - bScore;
            var indicator = delta > 0 ? "↑" : delta < 0 ? "↓" : "=";
            _output.WriteLine($"{key,-20} {bScore,-30:F2} {cScore,-30:F2} {delta:+0.00;-0.00} {indicator}");
        }

        // Candidate should not regress significantly (allow 0.5 tolerance)
        foreach (var key in baselineScores.Keys)
        {
            var regression = baselineScores[key] - candidateScores.GetValueOrDefault(key);
            Assert.True(
                regression <= 0.5,
                $"[{name}] {key}: candidate regressed by {regression:F2} (baseline={baselineScores[key]:F2}, candidate={candidateScores.GetValueOrDefault(key):F2})");
        }
    }

    private static async Task<ChatResponse> RunScenario(string model, List<string> turns)
    {
        var client = CreateChatClient(model);
        var history = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a supportive life coach. Be concise and empathetic.")
        };

        ChatResponse? response = null;
        foreach (var turn in turns)
        {
            history.Add(new ChatMessage(ChatRole.User, turn));
            response = await client.GetResponseAsync(history);
            history.AddRange(response.Messages);
        }

        return response!;
    }

    public static IEnumerable<object[]> GetScenarios()
    {
        var json = File.ReadAllText(Path.Combine("Scenarios", "coaching.json"));
        var scenarios = JsonSerializer.Deserialize<List<ScenarioDefinition>>(json)!;

        foreach (var scenario in scenarios)
        {
            yield return new object[]
            {
                scenario.Name,
                scenario.Turns.Select(t => t.User).ToList()
            };
        }
    }

    private static IChatClient CreateChatClient(string model)
    {
        return new OpenAI.OpenAIClient(ApiKey)
            .GetChatClient(model)
            .AsIChatClient();
    }
}

using System.Text.Json.Serialization;

namespace MyApp.Evals;

public record ScenarioDefinition
{
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    [JsonPropertyName("turns")]
    public List<Turn> Turns { get; init; } = [];

    [JsonPropertyName("expectations")]
    public Expectations Expectations { get; init; } = new();
}

public record Turn
{
    [JsonPropertyName("user")]
    public string User { get; init; } = "";
}

public record Expectations
{
    [JsonPropertyName("topic")]
    public string Topic { get; init; } = "";

    [JsonPropertyName("tone")]
    public string Tone { get; init; } = "";
}

