using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Xunit;
using Xunit.Abstractions;

namespace MyApp.Evals;

/// <summary>
/// Compare mode – runs the same scenarios against two model configurations
/// and reports side-by-side quality scores.
/// </summary>
public class CompareTests
{
    private readonly ITestOutputHelper _output;

    private static readonly string BaselineModel = Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini";
    private static readonly string CandidateModel = Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o";
    private static readonly string JudgeModel = Environment.GetEnvironmentVariable("EVAL_JUDGE_MODEL") ?? "gpt-4o";
    private static readonly string ApiKey = Environment.GetEnvironmentVariable("EVAL_API_KEY") ?? "";

    public CompareTests(ITestOutputHelper output)
    {
        _output = output;
    }

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Candidate_ScoredAgainstBaseline(string name, List<string> turns)
    {
        var judgeClient = CreateChatClient(JudgeModel);

        var baselineResponse = await RunScenario(BaselineModel, turns);
        var candidateResponse = await RunScenario(CandidateModel, turns);

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var baselineScores = new Dictionary<string, double>();
        var candidateScores = new Dictionary<string, double>();

        foreach (var evaluator in evaluators)
        {
            var baseResult = await evaluator.EvaluateAsync(turns, baselineResponse, judgeClient);
            var candResult = await evaluator.EvaluateAsync(turns, candidateResponse, judgeClient);

            foreach (var metric in baseResult)
            {
                if (metric.Value is NumericMetricValue num)
                    baselineScores[metric.Key] = num.Value ?? 0;
            }

            foreach (var metric in candResult)
            {
                if (metric.Value is NumericMetricValue num)
                    candidateScores[metric.Key] = num.Value ?? 0;
            }
        }

        // Report comparison
        _output.WriteLine($"Scenario: {name}");
        _output.WriteLine($"{"Metric",-20} {"Baseline (" + BaselineModel + ")",-30} {"Candidate (" + CandidateModel + ")",-30} Delta");
        _output.WriteLine(new string('-', 100));

        foreach (var key in baselineScores.Keys)
        {
            var bScore = baselineScores.GetValueOrDefault(key);
            var cScore = candidateScores.GetValueOrDefault(key);
            var delta = cScore - bScore;
            var indicator = delta > 0 ? "↑" : delta < 0 ? "↓" : "=";
            _output.WriteLine($"{key,-20} {bScore,-30:F2} {cScore,-30:F2} {delta:+0.00;-0.00} {indicator}");
        }

        // Candidate should not regress significantly (allow 0.5 tolerance)
        foreach (var key in baselineScores.Keys)
        {
            var regression = baselineScores[key] - candidateScores.GetValueOrDefault(key);
            Assert.True(
                regression <= 0.5,
                $"[{name}] {key}: candidate regressed by {regression:F2} (baseline={baselineScores[key]:F2}, candidate={candidateScores.GetValueOrDefault(key):F2})");
        }
    }

    private static async Task<ChatResponse> RunScenario(string model, List<string> turns)
    {
        var client = CreateChatClient(model);
        var history = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a supportive life coach. Be concise and empathetic.")
        };

        ChatResponse? response = null;
        foreach (var turn in turns)
        {
            history.Add(new ChatMessage(ChatRole.User, turn));
            response = await client.GetResponseAsync(history);
            history.AddRange(response.Messages);
        }

        return response!;
    }

    public static IEnumerable<object[]> GetScenarios()
    {
        var json = File.ReadAllText(Path.Combine("Scenarios", "coaching.json"));
        var scenarios = JsonSerializer.Deserialize<List<ScenarioDefinition>>(json)!;

        foreach (var scenario in scenarios)
        {
            yield return new object[]
            {
                scenario.Name,
                scenario.Turns.Select(t => t.User).ToList()
            };
        }
    }

    private static IChatClient CreateChatClient(string model)
    {
        return new OpenAI.OpenAIClient(ApiKey)
            .GetChatClient(model)
            .AsIChatClient();
    }
}

